+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.example.contact.MessageService.Message;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern
+            .compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
+
+    private final MessageService service;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<Message> grid = new Grid<>();
+    private boolean resetting;
+
+    public ContactView(MessageService service) {
+        this.service = service;
+        email.setPattern(null);
+        email.setManualValidation(true);
+        for (var f : new com.vaadin.flow.component.AbstractField[] { name,
+                email, phone, message }) {
+            f.addValueChangeListener(e -> {
+                if (!resetting) {
+                    send.setEnabled(true);
+                }
+            });
+        }
+        send.addClickListener(e -> submit());
+        send.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::text).setHeader("Message");
+        grid.setItems(service.findAll());
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), name,
+                email, phone, message, send, grid);
+    }
+
+    private void submit() {
+        boolean ok = true;
+        ok &= check(name, name.getValue().isBlank(), "Name is required");
+        String mail = email.getValue().trim();
+        String tel = phone.getValue().trim();
+        String emailError = null;
+        if (!mail.isEmpty() && !EMAIL.matcher(mail).matches()) {
+            emailError = "Enter a valid e-mail address";
+        } else if (mail.isEmpty() && tel.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+        ok &= check(email, emailError != null, emailError);
+        String text = message.getValue();
+        String msgError = null;
+        if (text.isBlank()) {
+            msgError = "Message is required";
+        } else if (text.length() > 500) {
+            msgError = "Message must be at most 500 characters";
+        }
+        ok &= check(message, msgError != null, msgError);
+        if (!ok) {
+            return;
+        }
+        service.add(new Message(name.getValue(), mail, tel, text));
+        resetting = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            resetting = false;
+        }
+        for (var f : new com.vaadin.flow.component.HasValidation[] { name,
+                email, phone, message }) {
+            f.setInvalid(false);
+        }
+        grid.setItems(service.findAll());
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean check(com.vaadin.flow.component.HasValidation field,
+            boolean failed, String error) {
+        field.setInvalid(failed);
+        if (failed) {
+            field.setErrorMessage(error);
+        }
+        return !failed;
+    }
+
+    private boolean dirty() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty()
+                || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!dirty()) {
+            return;
+        }
+        var action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard changes?");
+        dialog.add("You have unsent changes.");
+        Button keep = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.getFooter().add(keep, discard);
+        dialog.open();
+    }
+}
